#!/usr/bin/env python3
# ═══════════════════════════════════════════════════════════════════════
# OPENAPI  VERIFY — docs/openapi.json drift gate
#
# docs/openapi.json is a checked-in snapshot of the live /api-docs.json. It is
# not regenerated by any build step, so a new route leaves the snapshot stale
# and nothing fails. This gate regenerates the document from the same module
# the server serves it from (backend/src/openapi.ts) and fails if it no longer
# matches the snapshot.
#
# No database, no API, no .env: swagger-jsdoc parses the @openapi annotations
# in backend/src/routes/*.ts and nothing else.
#
# Usage: python scripts/verify/verify_openapi.py
#        python scripts/verify/verify_openapi.py --write   (refresh snapshot)
# Exit:  0 PASS  1 FAIL
# ═══════════════════════════════════════════════════════════════════════
import argparse
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
BE = os.path.join(ROOT, "backend")
# Relative to BE: cmd /c mis-parses an absolute path containing spaces.
TSX = os.path.join("node_modules", ".bin", "tsx.cmd")
SCRIPT = os.path.join("scripts", "openapi.ts")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--write", action="store_true", help="refresh docs/openapi.json instead of checking")
    args = ap.parse_args()

    print("=" * 74)
    print("OPENAPI VERIFY - docs/openapi.json " + ("refresh" if args.write else "drift gate"))
    print("=" * 74)

    if not os.path.exists(os.path.join(BE, TSX)):
        print(f"  FAIL  tsx not found at {os.path.join(BE, TSX)} (run: npm install in backend/)")
        sys.exit(1)

    cmd = ["cmd", "/c", TSX, SCRIPT] + (["--write"] if args.write else [])
    proc = subprocess.run(cmd, capture_output=True, text=True, cwd=BE, timeout=300)
    body = (proc.stdout or "").rstrip()
    if body:
        print(body)
    if proc.stderr and proc.stderr.strip():
        print(proc.stderr.rstrip())

    sys.exit(proc.returncode if proc.returncode in (0, 1) else 1)


if __name__ == "__main__":
    main()
